//! Glue between the Slint window and the worker thread. No device logic here.

use std::rc::Rc;
use std::time::Duration;

use mousetune_core::{Brightness, Dpi, DpiPair, Effect, Led, PollingRate};
use slint::{ComponentHandle, Model, ModelRc, SharedString, Timer, VecModel};

use crate::device_ops::Change;
use crate::state::{AppState, DeviceState, LedState, Section};
use crate::worker::{Event, Request, WorkerHandle};

/// Code generated by the Slint compiler; not ours to lint.
#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::unwrap_used,
    clippy::expect_used,
    missing_docs
)]
mod generated {
    slint::include_modules!();
}
pub use generated::{LedData, MainWindow, Screen, Theme};

const EFFECTS: [Effect; 3] = [Effect::Off, Effect::Static, Effect::Breathe];
const LEDS: [Led; 2] = [Led::Logo, Led::Scroll];
/// How long "Applied" stays visible.
const STATUS_LIFETIME: Duration = Duration::from_millis(1800);

/// Shows the window and runs the UI until it is closed.
///
/// `start` receives a sink for worker events and returns the running worker.
///
/// # Errors
///
/// Returns an error if the window cannot be created or run.
pub fn run(
    start: impl FnOnce(Box<dyn Fn(Event) + Send>) -> anyhow::Result<WorkerHandle>,
) -> anyhow::Result<()> {
    // Slint creates transparent winit windows by default; on recent macOS
    // the system title bar of a transparent window shows the desktop behind
    // it. MouseTune never needs transparency, so ask for an opaque window.
    slint::BackendSelector::new()
        .with_winit_window_attributes_hook(|attributes| attributes.with_transparent(false))
        .select()?;

    let window = MainWindow::new()?;

    let weak = window.as_weak();
    let sink = Box::new(move |event: Event| {
        let weak = weak.clone();
        // Ignored if the event loop has already ended.
        let _ = slint::invoke_from_event_loop(move || {
            if let Some(window) = weak.upgrade() {
                handle_event(&window, event);
            }
        });
    });
    let worker = Rc::new(start(sink)?);

    wire_callbacks(&window, &worker);
    window.run()?;
    Ok(())
}

/// Renders an [`AppState`] into the window. Used by the app and by the
/// snapshot tool.
pub fn present(window: &MainWindow, state: &AppState) {
    match state {
        AppState::Searching => window.set_screen(Screen::Searching),
        AppState::Unsupported => window.set_screen(Screen::Unsupported),
        AppState::NeedsPermission => window.set_screen(Screen::Permission),
        AppState::Busy => window.set_screen(Screen::Busy),
        AppState::Error(message) => {
            window.set_message(sentence(message));
            window.set_screen(Screen::Error);
        }
        AppState::Connected(device) => present_device(window, device),
    }
}

fn wire_callbacks(window: &MainWindow, worker: &Rc<WorkerHandle>) {
    let send = |worker: &Rc<WorkerHandle>, change: Option<Change>| {
        if let Some(change) = change {
            worker.send(Request::Apply(change));
        }
    };

    let w = Rc::clone(worker);
    window.on_apply_dpi(move |x, y| send(&w, dpi_change(x, y)));
    let w = Rc::clone(worker);
    window.on_apply_polling(move |index| {
        send(
            &w,
            index_into(&PollingRate::ALL, index).map(Change::Polling),
        );
    });
    let w = Rc::clone(worker);
    window.on_apply_effect(move |led, effect| {
        let change = index_into(&LEDS, led)
            .zip(index_into(&EFFECTS, effect))
            .map(|(led, effect)| Change::Effect(led, effect));
        send(&w, change);
    });
    let w = Rc::clone(worker);
    window.on_apply_brightness(move |led, percent| {
        let percent = u8::try_from(percent.clamp(0, 100)).unwrap_or(100);
        let change = index_into(&LEDS, led)
            .map(|led| Change::Brightness(led, Brightness::from_percent(percent)));
        send(&w, change);
    });
    let w = Rc::clone(worker);
    window.on_request_access(move || w.send(Request::GrantAccess));
    window.on_open_settings(open_settings);
}

/// Looks up a UI index (an `int` from Slint) in a table.
fn index_into<T: Copy>(table: &[T], index: i32) -> Option<T> {
    usize::try_from(index)
        .ok()
        .and_then(|i| table.get(i).copied())
}

/// Position of a value in a table, as a Slint `int` (-1 if absent).
fn position_of<T: PartialEq>(table: &[T], value: &T) -> i32 {
    table
        .iter()
        .position(|x| x == value)
        .and_then(|i| i32::try_from(i).ok())
        .unwrap_or(-1)
}

fn dpi_change(x: i32, y: i32) -> Option<Change> {
    let dpi = |value: i32| u16::try_from(value).ok().and_then(|v| Dpi::new(v).ok());
    Some(Change::Dpi(DpiPair {
        x: dpi(x)?,
        y: dpi(y)?,
    }))
}

fn open_settings() {
    let url = mousetune_hid::INPUT_MONITORING_SETTINGS_URL;
    #[cfg(target_os = "macos")]
    if let Err(error) = std::process::Command::new("open").arg(url).spawn() {
        tracing::warn!(%error, "could not open System Settings");
    }
    #[cfg(not(target_os = "macos"))]
    tracing::debug!(url, "System Settings link is only used on macOS");
}

fn handle_event(window: &MainWindow, event: Event) {
    // Every event settles pending slider edits (see TuneSlider.epoch).
    window.set_epoch(window.get_epoch().wrapping_add(1));
    match event {
        Event::State(state) => present(window, &state),
        Event::Applied(section) => set_status(window, section, "Applied", false),
        Event::Failed(section, message) => set_status(window, section, &message, true),
    }
}

fn present_device(window: &MainWindow, device: &DeviceState) {
    window.set_model_name(device.model.name().into());
    window.set_firmware(format!("{}.{}", device.firmware.0, device.firmware.1).into());
    window.set_serial(device.serial.as_str().into());
    window.set_dpi_x(f32::from(device.dpi.x.get()));
    window.set_dpi_y(f32::from(device.dpi.y.get()));
    if device.dpi.x != device.dpi.y {
        window.set_separate_xy(true);
    }
    window.set_polling_index(position_of(&PollingRate::ALL, &device.polling));
    update_leds(window, &device.leds);
    window.set_screen(Screen::Connected);
}

/// Updates LED rows in place when the set of LEDs is unchanged, so the cards
/// (and keyboard focus inside them) survive an apply.
fn update_leds(window: &MainWindow, leds: &[LedState]) {
    let current = window.get_leds();
    let same_layout = current.row_count() == leds.len()
        && current
            .iter()
            .zip(leds)
            .all(|(row, led)| row.id == position_of(&LEDS, &led.led));

    let row = |led: &LedState, old: Option<&LedData>| LedData {
        id: position_of(&LEDS, &led.led),
        name: led_title(led.led).into(),
        effect: led
            .effect
            .map_or(-1, |effect| position_of(&EFFECTS, &effect)),
        brightness: i32::from(led.brightness.percent()),
        status: old.map_or_else(SharedString::new, |old| old.status.clone()),
        status_is_error: old.is_some_and(|old| old.status_is_error),
    };

    if same_layout {
        for (index, led) in leds.iter().enumerate() {
            let old = current.row_data(index);
            let new = row(led, old.as_ref());
            if old.as_ref() != Some(&new) {
                current.set_row_data(index, new);
            }
        }
    } else {
        let rows: Vec<LedData> = leds.iter().map(|led| row(led, None)).collect();
        window.set_leds(ModelRc::from(Rc::new(VecModel::from(rows))));
    }
}

fn led_title(led: Led) -> &'static str {
    match led {
        Led::Logo => "Logo lighting",
        Led::Scroll => "Scroll wheel lighting",
    }
}

/// Core error messages are lowercase phrases; the UI shows sentences.
fn sentence(message: &str) -> SharedString {
    if message.is_empty() {
        return SharedString::new();
    }
    let mut chars = message.chars();
    let mut text: String = chars
        .next()
        .map(|c| c.to_uppercase().collect())
        .unwrap_or_default();
    text.push_str(chars.as_str());
    if !text.ends_with('.') {
        text.push('.');
    }
    text.into()
}

/// Shows feedback in a section; successes disappear after a moment.
fn set_status(window: &MainWindow, section: Section, text: &str, is_error: bool) {
    let text = if is_error {
        sentence(text)
    } else {
        text.into()
    };
    write_status(window, section, &text, is_error);
    if !is_error {
        let weak = window.as_weak();
        Timer::single_shot(STATUS_LIFETIME, move || {
            if let Some(window) = weak.upgrade() {
                write_status(&window, section, "", false);
            }
        });
    }
}

fn write_status(window: &MainWindow, section: Section, text: &str, is_error: bool) {
    match section {
        Section::Dpi => {
            window.set_dpi_status(text.into());
            window.set_dpi_status_is_error(is_error);
        }
        Section::Polling => {
            window.set_polling_status(text.into());
            window.set_polling_status_is_error(is_error);
        }
        Section::Led(led) => {
            let id = position_of(&LEDS, &led);
            let leds = window.get_leds();
            if let Some(index) = leds.iter().position(|row| row.id == id) {
                if let Some(mut row) = leds.row_data(index) {
                    row.status = text.into();
                    row.status_is_error = is_error;
                    leds.set_row_data(index, row);
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn errors_become_sentences() {
        assert_eq!(
            sentence("the mouse is busy, try again"),
            "The mouse is busy, try again."
        );
        assert_eq!(sentence("Already fine."), "Already fine.");
        assert_eq!(sentence(""), "");
    }

    #[test]
    fn ui_indexes_are_bounds_checked() {
        assert_eq!(index_into(&LEDS, 1), Some(Led::Scroll));
        assert_eq!(index_into(&LEDS, 2), None);
        assert_eq!(index_into(&LEDS, -1), None);
        assert_eq!(position_of(&EFFECTS, &Effect::Breathe), 2);
    }

    #[test]
    fn dpi_change_rejects_out_of_range_values() {
        assert!(dpi_change(1600, 800).is_some());
        assert!(dpi_change(50, 800).is_none());
        assert!(dpi_change(800, 7000).is_none());
    }
}
